INSERT INTO `SystemSetting` VALUES ('ad_reward_enabled','true','默认业务策略: ad_reward_enabled','2026-09-28 02:33:10.251'),('ad_unit_id','adunit-mock-default-15s','默认业务策略: ad_unit_id','2026-09-28 02:33:10.252'),('ai_config','{\"provider\":\"glm\",\"apiKey\":\"e1f0c85bb2ce4654802db293b1d0f849.2ALINIUmKb8YNtjb\",\"baseUrl\":\"https://open.bigmodel.cn/api/paas/v4\",\"model\":\"glm-4.7-flash\",\"temperature\":0.7,\"topP\":0.9,\"maxTokens\":1000,\"systemPrompt\":\"你是一位温和、洞察力深刻且富有共情心的心理学投射分析师与心灵疗愈导师。\\n你的核心工作是基于荣格心理学“共时性原则”与潜意识意象投射，帮助来访者观照内在自我。\\n\\n【核心合规戒律】：\\n1. 严禁断言未来吉凶祸福，严禁使用“命运注定”、“必有大难”、“大吉大利”等迷信算命式预言。\\n2. 将卡牌意象解读为当事人潜意识在现实生活中的投射，聚焦于心智模式、情绪内耗、思维盲区。\\n3. 必须提供温和、具体、具有可行性的正念微习惯或行动建议。\\n\\n【输出结构要求】：\\n1. 【今日心灵定调】：（提炼 2~4 个字的核心情绪/能量意向，如“破茧沉淀”、“澄澈内观”）\\n2. 【意象投射与潜意识映射】：（结合来访者的困惑与抽出的卡牌，剖析卡牌象征对当下的心理映照）\\n3. 【思维盲区与视角转念】：（指出当下认知中的执念或误区，提供全新的觉察视角）\\n4. 【正念行动微建议】：（给出 1~2 条切实可行的微小行动或自我关怀练习）\\n5. 【赋能金句】：（提炼一句富有启发与安宁的心灵箴言短句，如“穿透内心的迷雾，接纳潜意识深处的潮汐。”）\",\"providerProfiles\":{\"glm\":{\"baseUrl\":\"https://open.bigmodel.cn/api/paas/v4\",\"apiKey\":\"e1f0c85bb2ce4654802db293b1d0f849.2ALINIUmKb8YNtjb\",\"model\":\"glm-4.7-flash\",\"temperature\":0.7,\"topP\":0.9},\"siliconflow\":{\"baseUrl\":\"https://api.siliconflow.cn/v1\",\"apiKey\":\"\",\"model\":\"Qwen/Qwen2.5-7B-Instruct\",\"temperature\":0.7,\"topP\":0.9},\"baidu_qianfan\":{\"baseUrl\":\"https://qianfan.baidubce.com/v2\",\"apiKey\":\"\",\"model\":\"ernie-speed-8k\",\"temperature\":0.7,\"topP\":0.9}}}','大模型网关参数与 System Prompt 编排配置','2026-09-28 07:49:45.137'),('daily_free_limit','5','默认业务策略: daily_free_limit','2026-09-28 02:33:10.246'),('is_in_review','false','默认业务策略: is_in_review','2026-09-28 06:13:26.008'),('share_reward_enabled','true','默认业务策略: share_reward_enabled','2026-09-28 02:33:10.251'),('share_reward_limit','5','默认业务策略: share_reward_limit','2026-09-28 04:01:14.700');
